#!/usr/bin/env python3
"""Query ClinVar through NCBI E-utilities and expose the raw and parsed record."""

import json
import sys
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET


HGVS = "NM_003120.3(SPI1):c.143-2A>C"
BASE = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/"
COMMON = {"db": "clinvar", "tool": "GalaxyClinVarLookup", "retmax": "100"}


def fetch_json(endpoint, params):
    query = urllib.parse.urlencode(params)
    request = urllib.request.Request(
        BASE + endpoint + "?" + query,
        headers={"User-Agent": "GalaxyClinVarLookup/1.0"},
    )
    with urllib.request.urlopen(request, timeout=60) as response:
        return json.loads(response.read().decode("utf-8"))


def fetch_bytes(endpoint, params):
    query = urllib.parse.urlencode(params)
    request = urllib.request.Request(
        BASE + endpoint + "?" + query,
        headers={"User-Agent": "GalaxyClinVarLookup/1.0"},
    )
    with urllib.request.urlopen(request, timeout=120) as response:
        return response.read()


def local_name(tag):
    return tag.rsplit("}", 1)[-1]


def child_text(element, name):
    for child in element.iter():
        if local_name(child.tag) == name and child.text:
            return child.text.strip()
    return None


def xml_classifications(xml_bytes):
    root = ET.fromstring(xml_bytes)
    records = []
    for archive in root.iter():
        if local_name(archive.tag) != "VariationArchive":
            continue
        record = {
            "accession": archive.attrib.get("Accession"),
            "version": archive.attrib.get("Version"),
            "variation_id": child_text(archive, "VariationID"),
            "variation_type": child_text(archive, "VariationType"),
            "classifications": [],
        }
        for element in archive.iter():
            if local_name(element.tag) not in {
                "GermlineClassification",
                "SomaticClinicalImpact",
                "Oncogenicity",
            }:
                continue
            classification = {
                "type": local_name(element.tag),
                "description": child_text(element, "Description"),
                "review_status": child_text(element, "ReviewStatus"),
                "date_last_evaluated": child_text(element, "DateLastEvaluated"),
            }
            record["classifications"].append(classification)
        records.append(record)
    return records


def main():
    # The first two queries are exact ClinVar Variant Name searches.  The
    # remaining forms are a diagnostic for transcript/gene notation variants.
    queries = [
        f'"{HGVS}"[Variant Name]',
        f'"NM_003120.3:c.143-2A>C"[Variant Name]',
        f'NM_003120.3:c.143-2A>C[All Fields]',
        'SPI1[gene] AND "c.143-2A>C"[All Fields]',
    ]
    searches = []
    ids = []
    seen = set()
    for term in queries:
        response = fetch_json("esearch.fcgi", {**COMMON, "term": term, "retmode": "json"})
        id_list = response.get("esearchresult", {}).get("idlist", [])
        searches.append({"term": term, "ids": id_list, "count": response.get("esearchresult", {}).get("count")})
        for value in id_list:
            if value not in seen:
                seen.add(value)
                ids.append(value)

    summaries = {}
    if ids:
        summary = fetch_json(
            "esummary.fcgi",
            {**COMMON, "id": ",".join(ids), "retmode": "json"},
        )
        summaries = summary.get("result", {})

    raw_xml = b""
    parsed_records = []
    if ids:
        raw_xml = fetch_bytes(
            "efetch.fcgi",
            {
                "db": "clinvar",
                "rettype": "vcv",
                "is_variationid": "y",
                "from_esearch": "true",
                "id": ",".join(ids),
                "tool": "GalaxyClinVarLookup",
            },
        )
        parsed_records = xml_classifications(raw_xml)

    evidence = {
        "query_hgvs": HGVS,
        "source": "NCBI ClinVar via E-utilities",
        "searches": searches,
        "variation_ids": ids,
        "summaries": summaries,
        "vcv_classifications": parsed_records,
    }
    with open("clinvar_evidence.json", "w", encoding="utf-8") as handle:
        json.dump(evidence, handle, indent=2, sort_keys=True)
    with open("clinvar_raw.xml", "wb") as handle:
        handle.write(raw_xml)

    with open("result.tsv", "w", encoding="utf-8") as handle:
        handle.write("query_hgvs\tvariation_id\taccession\tclinical_significance\treview_status\n")
        rows = []
        for record in parsed_records:
            for classification in record["classifications"]:
                rows.append(
                    (
                        HGVS,
                        record.get("variation_id") or "",
                        record.get("accession") or "",
                        classification.get("description") or "",
                        classification.get("review_status") or "",
                    )
                )
        if not rows and ids:
            for value in ids:
                record = summaries.get(value, {})
                significance = record.get("clinical_significance", {})
                if isinstance(significance, dict):
                    significance = significance.get("description", "")
                handle.write(
                    "\t".join(
                        [
                            HGVS,
                            value,
                            str(record.get("accession", "")),
                            str(significance),
                            str(record.get("review_status", "")),
                        ]
                    )
                    + "\n"
                )
        else:
            for row in rows:
                handle.write("\t".join(row) + "\n")


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print(f"ClinVar lookup failed: {error}", file=sys.stderr)
        raise

